    @Test
    void futureHoldDoesNotBlockDestructionUntilEffective() throws Exception {
        String ev = uniqueKey("EV");
        intake("alice", ev);
        createHold("alice", uniqueKey("HOLD"), List.of(ev), now.plusHours(6), farFuture);

        String requestKey = uniqueKey("DREQ");
