    }

    @Test
    void destroyedEvidenceCannotBeHoldedAndHistoryIsQueryable() throws Exception {
        String ev = uniqueKey("EV");
        intake("alice", ev);
        String requestKey = uniqueKey("DREQ");
        submitDestruction("alice", uniqueKey("CMD"), requestKey, List.of(ev));
