    @Test
    void batchReleaseSucceedsAtomically() throws Exception {
        String ev1 = uniqueKey("EV");
        String ev2 = uniqueKey("EV");
        intake("alice", ev1);
        intake("alice", ev2);
        String hold1 = uniqueKey("HOLD");
